import {guidanceActions,observeServices,guidanceState,supplyNeeds} from './adventure-guidance.js?v=5.16.0';
import {RIVALS,equipRivalGear} from './npc-challenges.js?v=5.38';
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export function mountAdventureGuidance({getWorld,onOpen,onGrowth,onCraft,onSchool,onVendor,onSave}){const menu=document.querySelector('#menu-button'),badge=el('span','◆');badge.className='menu-growth-cue';badge.hidden=true;badge.setAttribute('aria-hidden','true');menu.append(badge);let current=[],lastSignature='',lastSeen=0;badge.onclick=e=>{e.stopPropagation();onOpen();};
return{visitVendor:onVendor,refresh(visible){const w=getWorld();if(!w)return;const now=performance.now();if(visible&&now-lastSeen>900){observeServices(w);lastSeen=now;}const s=w.state,signature=JSON.stringify([!!visible,!!s.story?.firstCore,s.chapter,s.scene,s.cores,s.supports,s.items,s.kakeya?.relics,s.rivals,s.guidance?.shops,s.resonance,s.physicalLore?.growthPoints,s.bosses,s.recruited?.map(id=>[id,s.heroes[id].level,s.skillGrid?.[id],s.heroes[id].loadout,s.heroes[id].doctrineSlots])]);if(signature===lastSignature)return;lastSignature=signature;current=guidanceActions(w.state);const gear=(w.state.rivals?.gear||[]).some(id=>!w.state.heroes.some(h=>h.rivalGear===id));badge.hidden=!visible||(!current.length&&!gear);menu.setAttribute('aria-label',badge.hidden?'Pause':'Pause · upgrades or restocking available');menu.title=badge.hidden?'Pause':'◆ Growth, equipment or supplies to review';},open(){onOpen();},panel(){const w=getWorld(),s=w.state,root=el('section');root.className='adventure-guidance';root.setAttribute('aria-label','Useful next steps');root.append(el('small','A LITTLE PREPARATION'),el('h3','Ready for the road'),el('p','The diamond appears for affordable growth, learned Mako, spare gear or low supplies near a known shop. It never spends points, chooses upgrades, buys items or interrupts a fight.'));current=guidanceActions(s);for(const a of current){const card=el('article');card.append(el('h4',a.title),el('p',a.detail));const b=el('button',a.kind==='growth'?'Inspect this companion’s next node':a.kind==='vendor'?'Guide me to this merchant':a.kind==='school'?'Review this school':'Review Crystal craft');b.onclick=()=>a.kind==='growth'?onGrowth(a.hero,a.node):a.kind==='craft'?onCraft(a.hero,a.mako):a.kind==='school'?onSchool(a.hero,a.school,a.node):onVendor(a.shop);card.append(b);if(a.kind==='vendor'){const merchant=el('p',a.shop.scene===s.scene?'Route only. Trading still requires your choice at the counter.':'This is a remembered location. Follow remembered rooms one doorway at a time; use the diamond to continue the trail.');card.append(merchant);}root.append(card);}for(const id of s.rivals?.gear||[]){const gear=RIVALS.find(r=>r.gear.id===id)?.gear;if(!gear)continue;const owner=s.heroes.find(h=>h.rivalGear===id),card=el('article');card.append(el('h4',gear.name),el('p','Power +'+gear.power+' · Health +'+gear.hp+(owner?' · equipped by '+owner.name: ' · recovered, not equipped')));if(!owner){const select=el('select');select.setAttribute('aria-label','Equip '+gear.name+' on companion');for(const hero of s.recruited)select.add(new Option(s.heroes[hero].name,hero));const b=el('button','Equip this keepsake');b.onclick=()=>{if(equipRivalGear(s,Number(select.value),id)){onSave();root.replaceWith(this.panel());}};card.append(select,b);}root.append(card);}if(!current.length&&!s.rivals?.gear?.length)root.append(el('p','Nothing urgent. Continue exploring; the diamond will return when there is something useful to review.'));return root;}};}
